const groups = args.groups;

phase("review");
const results = await parallel(groups.map(function (g) {
  return async function () {
    const prompt = PREAMBLE + "\nYOUR ASSIGNED FILES (group " + g.key + "):\n" + g.files.map(function (f) { return "- " + f; }).join("\n") + "\n" + g.note;
    const r = await agent(prompt, {
      key: "review-" + g.key,
      label: g.label,
      timeoutMs: 1800000,
      schema: {
        type: "object",
        properties: {
          key: { type: "string" },
          files_reviewed: { type: "array", items: { type: "string" } },
          lines_reviewed: { type: "number" },
          bugs_fixed: { type: "array" },
          bugs_reported: { type: "array" },
          needs_decision: { type: "array" },
          pinned_touched: { type: "boolean" }
        },
        required: ["key", "files_reviewed", "lines_reviewed", "bugs_fixed", "bugs_reported", "needs_decision", "pinned_touched"]
      }
    });
    return r;
  };
}), { concurrency: 6 });

phase("synthesize");
const done = results.filter(function (r) { return r !== null; });
log("groups completed: " + done.length + " of " + groups.length);

const synth = await agent(synthPrompt, {
  key: "synthesize",
  label: "Synthesize audit",
  timeoutMs: 900000,
  schema: {
    type: "object",
    properties: {
      message: { type: "string" },
      total_files: { type: "number" },
      total_lines: { type: "number" },
      total_fixed: { type: "number" },
      total_reported: { type: "number" },
      pinned_ok: { type: "boolean" },
      needs_decision: { type: "array" }
    },
    required: ["message", "total_files", "total_lines", "total_fixed", "total_reported", "pinned_ok", "needs_decision"]
  }
});

return { message: synth.message, files: synth.total_files, lines: synth.total_lines, fixed: synth.total_fixed, reported: synth.total_reported, pinned_ok: synth.pinned_ok, needs_decision: synth.needs_decision };

phase("remediate");
const results = await parallel(ITEMS.map(function (it) {
  return async function () {
    const r = await agent(it.brief, {
      key: it.key,
      label: it.title,
      timeoutMs: 10800000,
      schema: {
        type: "object",
        properties: {
          item: { type: "string" },
          verdict: { type: "string" },
          summary: { type: "string" },
          commits: { type: "array", items: { type: "string" } },
          blocked_reason: { type: "string" }
        },
        required: ["item", "verdict", "summary"]
      }
    });
    return r;
  };
}), { concurrency: 5 });

